451	export type WorkingHours = { weekday: number; start: string; end: string };   // 'HH:MM', in the mentor's own time zone
452	export type Mentor = { id: number; name: string; email: string; bio: string; subjects: string[]; timeZone: string; hours: WorkingHours[] };
453	export type ActiveBooking = { mentorId: number; startsAt: Date; mentorLocalDate: string };
454	export type Slot = { startsAt: Date; available: boolean };
455	export function isBookableTime(startsAt: Date, now: Date): boolean;            // on the UTC hour, within [now+120min, now+14d]
456	export function worksAt(mentor: Mentor, startsAt: Date): boolean;              // the whole class fits one working-hours window
