581	- Produces (`src/server/bookings.ts`):
582	
583	```ts
584	export type BookingInput = { startsAt: Date; parentName: string; parentEmail: string; childName: string; parentTimeZone: string };
585	export type Booking = BookingInput & { id: string; mentorId: number; mentorLocalDate: string; classLink: string; cancelledAt: Date | null };
586	export type BookResult = { ok: true; booking: Booking } | { ok: false; code: 'SLOT_UNAVAILABLE' };
587	export function newClassLink(): string;                                              // https://classroom.example/trial/<random>
588	export async function loadMentors(pool: Pool): Promise<Mentor[]>;                   // with hours ('HH:MM'), ordered by id
589	export async function loadActiveBookings(pool: Pool, from: Date, to: Date): Promise<ActiveBooking[]>;  // from <= starts_at < to
590	export async function bookSlot(pool: Pool, input: BookingInput, now: Date, hooks?: { beforeInsert?: () => Promise<void> }): Promise<BookResult>;
591	export async function getBookingWithMentor(pool: Pool, id: string): Promise<{ booking: Booking; mentor: Mentor } | null>;
592	// src/server/test-db.ts (test-only)
593	export async function expectBookingRulesHold(pool: Pool): Promise<void>;
594	```
595	
596	- [ ] **Step 1: Write the failing tests** in `src/server/bookings.test.ts`
597	  - Each test gets a fresh database: `beforeEach` runs `createTestDb`, and `afterEach` runs `drop`.
598	  - Shared helpers:
599	    - `NOW = new Date('2026-10-20T12:00:00Z')`.
600	    - `ukHours`: weekdays 1–5, `'20:30'–'23:30'`.
601	    - `usHours`: weekdays 0, 2, 3, 4, 5, 6, `'02:30'–'07:30'`.
602	    - `input(iso)`: a London parent, Asha Patel / Rohan.
603	    - `sleep(ms)`.
604	    - `seededPick(seed)`: a 3-line linear congruential generator returning `(list) => list[index]`.
605	
606	```ts
607	test('assigns the least-booked mentor, then the lowest id', async () => {
608	  const a = await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: ukHours });
609	  const b = await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: ukHours });
610	  const first = await bookSlot(pool, input('2026-10-27T15:00:00Z'), NOW);
611	  const second = await bookSlot(pool, input('2026-10-27T16:00:00Z'), NOW);
612	  expect([first, second].map((r) => r.ok && r.booking.mentorId)).toEqual([a, b]);
613	});
614	
615	test("stores the instant and the date in the mentor's own time zone", async () => {
616	  await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: [{ weekday: 2, start: '06:30', end: '07:30' }] });
617	  const result = await bookSlot(pool, input('2026-10-27T01:00:00Z'), NOW); // Mon 6:00 PM in Los Angeles
618	  expect(result).toMatchObject({ ok: true, booking: { mentorLocalDate: '2026-10-27' } });
619	  expect(result.ok && result.booking.classLink).toMatch(/^https:\/\/classroom\.example\/trial\/[\w-]{8,}$/);
620	  const { rows } = await pool.query('select starts_at, mentor_local_date from bookings');
621	  expect([rows[0].starts_at.toISOString(), rows[0].mentor_local_date]).toEqual(['2026-10-27T01:00:00.000Z', '2026-10-27']);
622	});
623	
624	test('cancelled bookings free both the hour and the cap', async () => {
625	  await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: ukHours });
626	  const first = await bookSlot(pool, input('2026-10-27T15:00:00Z'), NOW);
627	  await bookSlot(pool, input('2026-10-27T16:00:00Z'), NOW);
628	  expect(await bookSlot(pool, input('2026-10-27T17:00:00Z'), NOW)).toEqual({ ok: false, code: 'SLOT_UNAVAILABLE' });
629	  await pool.query('update bookings set cancelled_at = now() where id = $1', [first.ok && first.booking.id]);
630	  expect((await bookSlot(pool, input('2026-10-27T15:00:00Z'), NOW)).ok).toBe(true);
631	});
632	
633	test('refuses times that cannot be booked', async () => {
634	  await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: ukHours });
635	  // off the hour, too soon, beyond 14 days, nobody works on Sunday
636	  for (const t of ['2026-10-27T15:30:00Z', '2026-10-20T13:00:00Z', '2026-11-04T15:00:00Z', '2026-10-25T15:00:00Z'])
637	    expect(await bookSlot(pool, input(t), NOW)).toEqual({ ok: false, code: 'SLOT_UNAVAILABLE' });
638	});
639	
640	test('same-hour race: exactly one booking per free mentor', async () => {
641	  const ids = [];
642	  for (let i = 0; i < 3; i++) ids.push(await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: ukHours }));
643	  const results = await Promise.all(Array.from({ length: 10 }, () => bookSlot(pool, input('2026-10-27T16:00:00Z'), NOW)));
644	  const booked = results.flatMap((r) => (r.ok ? [r.booking.mentorId] : []));
645	  expect(booked).toHaveLength(3);
646	  expect(new Set(booked)).toEqual(new Set(ids));
647	  expect(results.filter((r) => !r.ok)).toHaveLength(7);
648	});
649	
650	test('cap race: the lock makes the second booking wait, then refuse', async () => {
651	  await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: ukHours });
652	  await bookSlot(pool, input('2026-10-27T15:00:00Z'), NOW);
653	  const pause = { beforeInsert: () => sleep(100) };
654	  const results = await Promise.all([
655	    bookSlot(pool, input('2026-10-27T16:00:00Z'), NOW, pause),
656	    bookSlot(pool, input('2026-10-27T17:00:00Z'), NOW, pause),
657	  ]);
658	  expect(results.filter((r) => r.ok)).toHaveLength(1);
659	  const { rows } = await pool.query(`select count(*)::int as n from bookings where mentor_local_date = '2026-10-27' and cancelled_at is null`);
660	  expect(rows[0].n).toBe(2);
661	});
662	
663	test('a random burst keeps every rule', async () => {
664	  for (let i = 0; i < 5; i++) await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: ukHours });
665	  for (let i = 0; i < 5; i++) await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: usHours });
666	  const mentors = await loadMentors(pool);
667	  const open = buildSlots(mentors, [], NOW).map((s) => s.startsAt.toISOString());
668	  const pick = seededPick(42);
669	  const results = await Promise.all(Array.from({ length: 80 }, () => bookSlot(pool, input(pick(open)), NOW)));
670	  expect(results.some((r) => r.ok)).toBe(true);
671	  await expectBookingRulesHold(pool);
672	});
