// faithful-to-plan prototype of src/shared/time.ts (tasks 1-2)
const cache = new Map<string, Intl.DateTimeFormat>();
function fmt(locale: string, opts: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const k = locale + JSON.stringify(opts);
  let f = cache.get(k);
  if (!f) { f = new Intl.DateTimeFormat(locale, opts); cache.set(k, f); }
  return f;
}
const part = (parts: Intl.DateTimeFormatPart[], t: string) => parts.find((p) => p.type === t)?.value ?? '';

export function isValidTimeZone(tz: string): boolean {
  if (!(tz === 'UTC' || tz.includes('/'))) return false;
  try { new Intl.DateTimeFormat('en-US', { timeZone: tz }); return true; } catch { return false; }
}
export function offsetMinutes(at: Date, tz: string): number {
  const s = part(fmt('en-US', { timeZone: tz, timeZoneName: 'longOffset' }).formatToParts(at), 'timeZoneName');
  const m = /^GMT(?:([+-])(\d\d):(\d\d))?$/.exec(s);
  if (!m) throw new Error('bad offset ' + s);
  if (!m[1]) return 0;
  return (m[1] === '-' ? -1 : 1) * (Number(m[2]) * 60 + Number(m[3]));
}
export function localDate(at: Date, tz: string): string {
  const p = fmt('en-US', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(at);
  return `${part(p, 'year')}-${part(p, 'month')}-${part(p, 'day')}`;
}
export function weekdayOf(date: string): number {
  const [y, m, d] = date.split('-').map(Number);
  return new Date(Date.UTC(y!, m! - 1, d!)).getUTCDay();
}
export function addDays(date: string, days: number): string {
  const [y, m, d] = date.split('-').map(Number);
  return new Date(Date.UTC(y!, m! - 1, d! + days)).toISOString().slice(0, 10);
}
export function zonedTimeToInstant(date: string, time: string, tz: string): Date {
  const [y, m, d] = date.split('-').map(Number);
  const [hh, mm, ss = 0] = time.split(':').map(Number);
  const wall = Date.UTC(y!, m! - 1, d!, hh!, mm!, ss);
  const early = offsetMinutes(new Date(wall - 86_400_000), tz);
  const late = offsetMinutes(new Date(wall + 86_400_000), tz);
  const valid = [early, late]
    .map((o) => wall - o * 60_000)
    .filter((t) => offsetMinutes(new Date(t), tz) * 60_000 === wall - t);
  return new Date(valid.length ? Math.min(...valid) : wall - early * 60_000);
}
export function formatOffset(minutes: number): string {
  if (minutes === 0) return 'GMT';
  const sign = minutes < 0 ? '-' : '+';
  const a = Math.abs(minutes);
  const h = Math.floor(a / 60), mi = a % 60;
  return `GMT${sign}${h}${mi ? ':' + String(mi).padStart(2, '0') : ''}`;
}
const LOCALES = ['en-US', 'en-GB', 'en-IE', 'en-IN', 'en-CA', 'en-AU'];
export function zoneAbbreviation(at: Date, tz: string): string {
  for (const l of LOCALES) {
    const n = part(fmt(l, { timeZone: tz, timeZoneName: 'short' }).formatToParts(at), 'timeZoneName');
    if (!/^(GMT|UTC)[+-]/.test(n)) return n;
  }
  return formatOffset(offsetMinutes(at, tz));
}
const ALIAS: Record<string, string> = { 'Asia/Calcutta': 'Kolkata', 'Europe/Kiev': 'Kyiv', 'Asia/Saigon': 'Ho Chi Minh City' };
export function cityName(tz: string): string { return ALIAS[tz] ?? tz.split('/').at(-1)!.replaceAll('_', ' '); }
export function canonicalTimeZone(tz: string): string { return new Intl.DateTimeFormat('en', { timeZone: tz }).resolvedOptions().timeZone; }
export function formatTime(at: Date, tz: string): string {
  return fmt('en-US', { timeZone: tz, hour: 'numeric', minute: '2-digit' }).format(at).replace(/ /g, ' ');
}
export function formatDate(at: Date, tz: string): string {
  return fmt('en-GB', { timeZone: tz, weekday: 'short', day: 'numeric', month: 'short' }).format(at);
}
export function formatDateWithYear(at: Date, tz: string): string {
  const y = part(fmt('en-GB', { timeZone: tz, year: 'numeric' }).formatToParts(at), 'year');
  return `${formatDate(at, tz)} ${y}`;
}
export function formatDayKey(key: string): string { return formatDate(new Date(key + 'T12:00:00Z'), 'UTC'); }
export function formatZone(at: Date, tz: string): string { return `${zoneAbbreviation(at, tz)} (${cityName(tz)})`; }
export function formatWhen(at: Date, tz: string): string { return `${formatDate(at, tz)}, ${formatTime(at, tz)} ${formatZone(at, tz)}`; }
export function formatSpan(start: Date, end: Date, tz: string): string {
  const s = formatTime(start, tz), e = formatTime(end, tz);
  if (offsetMinutes(start, tz) !== offsetMinutes(end, tz))
    return `${s} ${zoneAbbreviation(start, tz)}–${e} ${zoneAbbreviation(end, tz)} (${cityName(tz)})`;
  const [st, sp] = s.split(' '), [, ep] = e.split(' ');
  if (sp === ep) return `${st}–${e} ${formatZone(start, tz)}`;
  return `${s}–${e} ${formatZone(start, tz)}`;
}
export function formatZoneOption(at: Date, tz: string): string { return `${cityName(tz)} (${formatOffset(offsetMinutes(at, tz))})`; }

