// faithful-to-plan prototype of src/server/slots.ts (task 4)
import { addDays, localDate, weekdayOf, zonedTimeToInstant } from './time.ts';
export const CLASS_MINUTES = 60, LEAD_MINUTES = 120, HORIZON_DAYS = 14, DAILY_CAP = 2;
export type WorkingHours = { weekday: number; start: string; end: string };
export type Mentor = { id: number; name: string; email: string; bio: string; subjects: string[]; timeZone: string; hours: WorkingHours[] };
export type ActiveBooking = { mentorId: number; startsAt: Date; mentorLocalDate: string };
export type Slot = { startsAt: Date; available: boolean };
const H = 3_600_000;
export function isBookableTime(startsAt: Date, now: Date): boolean {
  const t = startsAt.getTime();
  return t % H === 0 && t >= now.getTime() + LEAD_MINUTES * 60_000 && t <= now.getTime() + HORIZON_DAYS * 86_400_000;
}
function startsInWindow(date: string, h: WorkingHours, tz: string): number[] {
  const ws = zonedTimeToInstant(date, h.start, tz).getTime();
  const we = zonedTimeToInstant(date, h.end, tz).getTime();
  const out: number[] = [];
  for (let s = Math.ceil(ws / H) * H; s + CLASS_MINUTES * 60_000 <= we; s += H) out.push(s);
  return out;
}
export function worksAt(mentor: Mentor, startsAt: Date): boolean {
  const date = localDate(startsAt, mentor.timeZone);
  return mentor.hours.some((h) => h.weekday === weekdayOf(date) && startsInWindow(date, h, mentor.timeZone).includes(startsAt.getTime()));
}
export function classStarts(mentor: Mentor, from: Date, to: Date): Date[] {
  const tz = mentor.timeZone, set = new Set<number>();
  for (let d = addDays(localDate(from, tz), -1); d <= addDays(localDate(to, tz), 1); d = addDays(d, 1))
    for (const h of mentor.hours) if (h.weekday === weekdayOf(d))
      for (const s of startsInWindow(d, h, tz)) if (s >= from.getTime() && s <= to.getTime()) set.add(s);
  return [...set].sort((a, b) => a - b).map((s) => new Date(s));
}
export function buildSlots(mentors: Mentor[], bookings: ActiveBooking[], now: Date): Slot[] {
  const from = new Date(now.getTime() + LEAD_MINUTES * 60_000), to = new Date(now.getTime() + HORIZON_DAYS * 86_400_000);
  const taken = new Set(bookings.map((b) => `${b.mentorId}|${b.startsAt.getTime()}`));
  const count = new Map<string, number>();
  for (const b of bookings) count.set(`${b.mentorId}|${b.mentorLocalDate}`, (count.get(`${b.mentorId}|${b.mentorLocalDate}`) ?? 0) + 1);
  const avail = new Map<number, boolean>();
  for (const m of mentors) for (const s of classStarts(m, from, to)) {
    const open = !taken.has(`${m.id}|${s.getTime()}`) && (count.get(`${m.id}|${localDate(s, m.timeZone)}`) ?? 0) < DAILY_CAP;
    avail.set(s.getTime(), (avail.get(s.getTime()) ?? false) || open);
  }
  return [...avail].sort((a, b) => a[0] - b[0]).map(([t, available]) => ({ startsAt: new Date(t), available }));
}

